# THE ONKELOS ROWS of Numbers 26:1-65 (THE NUMBERS WALK sitting 8 — THE SECOND CENSUS, 2026-09-11): the command, the roster by families
# and counts, Korach recalled, the land by count and by lot, the Levites, the close. The Aramaic and the Hebrew CUT by consonants
# (census_ink.H / census_ink.A); 26:1's row carries 25:19's head (read at sitting 7 — the export's join). THE ROSTER VERSES' ROWS ARE
# BUILT FROM THE TOKENS THEMSELVES: the name / family pairs read off the verse (the store's own glosses), the translation's "seed-group"
# pairs read off the shelf's row — nothing typed for a verse whose whole content is names.
from census_ink import *
R = {}
def row(c, v, verdict, prose): R[(c, v)] = (verdict, prose)
def ex(c, v, n): return f'{numword(n)}'
def roster(v, note=''):
    """the family pairs of a roster verse, cut from the ink and the shelf: '(le-)Name — the family of the Name-ite'"""
    w = words('Num', 26, v); ar = aramaic(26, v)
    pairs = [(w[i - 1], w[i + 1]) for i, x in enumerate(w) if x == 'משפחת' and 0 < i < len(w) - 1]
    ink = '; '.join(f'"{H(26, v, a, "משפחת", b)}" ("{sg(26, v, a)} — the family of {sg(26, v, b)}")' for a, b in pairs)
    apairs = [(ar[i - 1], ar[i + 1]) for i, x in enumerate(ar) if x == 'זרעית' and 0 < i < len(ar) - 1]
    aram = '; '.join(f'{A(26, v, a, "זרעית", b)}' for a, b in apairs)
    return f'{ink} → {aram} ("seed-group" for family, the translation\'s word at every seat){note}'
def cnt(v, tribe):
    n = C26[tribe]; d = DELTA[tribe]
    return f'{numword(n)} — chapter 1\'s {numword(C1[tribe])} ({"+" if d > 0 else "−"}{numword(abs(d))}), the parser reading both'

row(26, 1, 'MATERIAL', f'THE LORD SAID TO MOSES AND TO ELEAZAR — THE CENSUS ADDRESSED TO THE SON WHERE THE FIRST WAS TO THE FATHER; THE COMMAND UNDATED, ITS DATE THE BROKEN HALF-VERSE. "{H(26, 1, "ויאמר", "יהוה", "אל", "משה", "ואל", "אלעזר", "בן", "אהרן", "הכהן")}" ("and the LORD SAID to Moses and to Eleazar son of Aaron the priest" — "said", not "spoke"; "to Moses and to Eleazar" at three seats, 26:1, 31:12, 32:2 — the pair that takes over from "to Moses and to Aaron" (eleven times in the book before Aaron\'s death at 20:28); 1:1 was DATED to the day — "in the wilderness of Sinai, in the tent of meeting, on the first of the second month of the second year" — and 26:1 carries NO date: its time is 25:19\'s three words, "and it was after the plague", the half-verse broken by the mid-verse pause and joined by the export into this row (read at sitting 7); computed) → {A(26, 1, "ואמר", "יי", "למשה", "ולאלעזר", "בר", "אהרן", "כהנא", "למימר")} ("and the LORD said to Moses and to Eleazar son of Aaron the priest, saying"). The register: "and He said".')
row(26, 2, 'MATERIAL', f'LIFT THE HEAD — THE FIRST CENSUS\'S COMMAND WITH FIVE CLAUSES DROPPED; THE TRANSLATION MAKES THE IDIOM A COUNT. "{H(26, 2, "שאו", "את", "ראש", "כל", "עדת", "בני", "ישראל")}" ("LIFT THE HEAD of all the congregation of the children of Israel" — 1:2\'s opening word for word) "{H(26, 2, "מבן", "עשרים", "שנה", "ומעלה", "לבית", "אבתם", "כל", "יצא", "צבא", "בישראל")}" ("from twenty years old and upward, by their fathers\' house, all who go out to the host in Israel" — 1:2-3\'s clauses with FIVE DROPPED: "by their families", "by the number of names", "every male by their polls", "you shall count them by their hosts", "you and Aaron" (the dropped words computed by set difference; "from twenty years old and upward" twenty-three Bible seats, "all who go out to the host" fifteen — fourteen in chapter 1 and this; the parser reads 20); computed) → {A(26, 2, "קבילו", "ית", "חשבן", "כל", "כנשתא", "דבני", "ישראל")} ("RECEIVE THE COUNT of all the congregation of the children of Israel" — the head-lifting idiom made a plain count, cut from the shelf\'s bytes); {A(26, 2, "מבר", "עשרין", "שנין", "ולעלא", "לבית", "אבהתהון", "כל", "נפק", "חילא", "בישראל")} ("from twenty years and upward, by their fathers\' house, all who go out to the host in Israel"). No narrative verb — the LORD\'s speech.')
row(26, 3, 'MATERIAL', f'MOSES AND ELEAZAR SPOKE [THEM] — THE OBJECT WITHOUT ITS VERB; THE TRANSLATION SUPPLIES "TO COUNT"; THE PLAINS OF MOAB BY THE JORDAN OF JERICHO. "{H(26, 3, "וידבר", "משה", "ואלעזר", "הכהן", "אתם")}" ("and Moses and Eleazar the priest spoke — THEM" — the object marker with the pronoun "them" (tagged an object, not "with them") and no verb of counting to take it: the ink\'s ellipsis; "Moses and Eleazar" seven seats from 20:28 on, the pair that replaces "Moses and Aaron" — which stands in this chapter only at 26:64, the first census recalled; computed) → {A(26, 3, "ומליל", "משה", "ואלעזר", "כהנא", "אמרו", "לממני", "יתהון")} ("and Moses and Eleazar the priest spoke, SAYING TO COUNT THEM" — the translation SUPPLIES the counting verb the ink omits, cut from the shelf\'s bytes); "{H(26, 3, "בערבת", "מואב", "על", "ירדן", "ירחו")}" ("in the plains of Moab by the Jordan of Jericho" — 22:1\'s camp; "in the plains of Moab" nine Bible seats, "by the Jordan of Jericho" seven, all in Numbers; computed) → {A(26, 3, "במישריא", "דמואב", "על", "ירדנא", "דירחו")} ("in the plains of Moab by the Jordan of Jericho"). The register: "and he spoke".')
row(26, 4, 'MATERIAL', f'FROM TWENTY YEARS OLD — AS THE LORD COMMANDED MOSES; AND THE CHILDREN OF ISRAEL WHO WENT OUT OF EGYPT — THE EXODUS GENERATION NAMED AT THE HEAD OF ITS REPLACEMENTS\' ROSTER. "{H(26, 4, "מבן", "עשרים", "שנה", "ומעלה", "כאשר", "צוה", "יהוה", "את", "משה")}" ("from twenty years old and upward, as the LORD commanded Moses" — 1:3\'s age band by reference to the first command) "{H(26, 4, "ובני", "ישראל", "היצאים", "מארץ", "מצרים")}" ("and the children of Israel WHO WENT OUT OF THE LAND OF EGYPT" — the participle phrase\'s one seat; a verse without a main verb, its clauses hanging on 26:2\'s command: the ink names the generation that left Egypt as the subject of a census in which, 26:64 will say, not a man of it is counted; computed) → {A(26, 4, "כמא", "די", "פקיד", "יי", "ית", "משה", "ובני", "ישראל", "די", "נפקו", "מארעא", "דמצרים")} ("as the LORD commanded Moses and the children of Israel who went out of the land of Egypt" — the syntax kept as it stands). No narrative verb.')
row(26, 5, 'MATERIAL', f'REUBEN THE FIRSTBORN OF ISRAEL — THE CLAUSE OF 1:20 SPELLED FULL; THE ROSTER OPENS WITH HANOCH BARE OF ITS PREPOSITION; THE FAMILY FORM ה-NAME-י BEGINS. "{H(26, 5, "ראובן", "בכור", "ישראל")}" ("Reuben, the FIRSTBORN of Israel" — the clause of 1:20 ("the sons of Reuben, Israel\'s firstborn") and of Genesis 46:8 ("Jacob\'s firstborn, Reuben") — spelled DEFECTIVE there and PLENE here (the vav present at 26:5, the cholam alone at 1:20 — computed on the bytes); the plene clause\'s other seats 1 Chronicles 5:1, 5:3 — "for he was the firstborn, but... the birthright was given to the sons of Joseph"); "{H(26, 5, "בני", "ראובן", "חנוך", "משפחת", "החנכי", "לפלוא", "משפחת", "הפלאי")}" ("the sons of Reuben: HANOCH, the family of the Hanochite; of PALLU, the family of the Palluite" — Hanoch stands BARE where Pallu carries "of" (le-): three tribe-heads open bare — Hanoch, Tola (26:23), Iezer (26:30) — the other eleven with the preposition (computed); THE FAMILY FORM: the article + the name + the gentilic yod, "the Hanochite", sixty-eight such forms in the chapter, sixty-five family gentilics, FIFTY-SEVEN FAMILIES in the twelve tribes and eight in Levi, "family of" seventy-eight times — chapter 1 has the word NOT ONCE (it counts "by the number of names"), computed) → {A(26, 5, "ראובן", "בוכרא", "דישראל", "בני", "ראובן", "חנוך", "זרעית", "חנוך", "לפלוא", "זרעית", "פלוא")} ("Reuben the firstborn of Israel; the sons of Reuben: Hanoch, the SEED-GROUP of Hanoch; of Pallu, the seed-group of Pallu" — the family made a seed-group, the gentilic dropped, the bare Hanoch kept bare; cut from the shelf\'s bytes). No narrative verb.')
